// Componente del Formulario de creación de Blog
import React from 'react'
import { useCampo } from '../../hooks/useCampo' // Hook personalizado para manejar los campos del formulario
import { useBlogs } from '../../contextos/BlogsContexto' // Hook personalizado que envuelve el contexto

const AñadirBlog = () => {
    const { crearBlog } = useBlogs() // Instancia para la creación de blogs usando context

    // Instancia para la entrada de datos con el hook useCampo
    const titulo = useCampo('titulo', 'text')
    const autor = useCampo('autor', 'text')
    const url = useCampo('url', 'text')

    // Función para limpiar los campos del formulario
    const limpiarFormulario = () => {
        titulo.limpiar()
        autor.limpiar()
        url.limpiar()
    }

    // Función para añadir un blog
    const añadirBlog = (e) => {
        e.preventDefault()
        const nuevoBlog = {
            titulo: titulo.inputProps.value,
            autor: autor.inputProps.value,
            url: url.inputProps.value,
            likes: 0
        }
        crearBlog(nuevoBlog) // Ejecuta la mutación crearBlog desde el hook
        limpiarFormulario() // Limpia el formulario al añadir el blog
    } 

    return (
        <div>
            <h2>Añadir Nuevo Blog</h2>
            <form onSubmit={añadirBlog}>
                <div>
                    Titulo del Blog:
                    <input {...titulo.inputProps} />
                </div>
                <div>
                    Autor del Blog:
                    <input {...autor.inputProps} />
                </div>
                <div>
                    Url del Blog:
                    <input {...url.inputProps} />
                </div>
                <button type='submit'>Añadir</button>
                <button type='button' onClick={limpiarFormulario}>Limpiar</button>
            </form>
        </div>
    )
}

export default AñadirBlog