import axios from 'axios' // Librería para hacer peticiones (get, post, delete...)

// Url del backend
const baseUrl = '/api/blogs'

// Obtener los blogs
export const obtenerBlogs = () => {
    // Solicitud get al backend
    return axios.get(baseUrl).then(res => res.data)
}

// Crear nuevo blog
export const crear = (nuevoBlog) => {
    // Solicitud post al backend
    return axios.post(baseUrl, nuevoBlog).then(res => res.data)
}

// Eliminar un blog
export const eliminar = (blogEliminado) => {
    // Solicitud delete al backend
    return axios.delete(`${baseUrl}/${blogEliminado.id}`, blogEliminado)
}

// Dar like a un blog
export const like = (id) => {
    // Solicitud post al backend
    return axios.post(`${baseUrl}/${id}/likes`)
}