// Componente para blog individual
import React from 'react'
const Blog = ({ blog, handleEliminar, handleLike }) => {
    return (
        <div>
            <h2><strong> {blog.titulo} </strong></h2>
            <h3> {blog.autor} </h3>
            <p> <em> URL: </em> { blog.url } </p>
            <p> { blog.likes } likes </p>
            <button onClick={handleEliminar}> <strong> Eliminar Blog </strong> </button>
            <button onClick={handleLike}> <strong> Like </strong> </button>
        </div>
    )
}

export default Blog