// Componente que encapsula todos los providers
import React from 'react'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query' // Libreria de query para proveer los componentes
// Importación de los Providers
import { BlogsProvider } from './contextos/BlogsContexto'
// Librería Router para enrutar
import { BrowserRouter as Router } from 'react-router-dom'

// Cliente Query (para manerjar las consultas a la API)
const queryClient = new QueryClient()

// Componente con los providers
const AppProviders = ({ children }) => {
    return (
        <QueryClientProvider client={queryClient}>
            <Router>
            <BlogsProvider>
                { children }
            </BlogsProvider>
            </Router>
        </QueryClientProvider>
    )
}

export default AppProviders