// Módulo para las mutaciones del estado (crear, likes, eliminar)
import { useMutation, useQueryClient } from '@tanstack/react-query' // Mutaciones -- Manejar el caché
import { crear, eliminar, like } from '../servicios/blogs_servicios'  // Servicios

// Mutación para crear un nuevo blog
export const useCrearBlog = () => {
    // Manejar lac caché
    const queryClient = useQueryClient()
    return useMutation({
        mutationFn: crear, // Referencia al servicio
        // Si la mutación es exitosa
        onSuccess: (nuevoBlog) => {
            const blogs = queryClient.getQueryData(['blogs']) || []
            queryClient.setQueryData(['blogs'], blogs.concat(nuevoBlog))
        },
        // Si la mutación falla
        onError: (error) => {
            console.error('Error al crear el blog:', error.response?.data?.error || error.message)
        }
    })
}

// Mutación para eliminar un blog
export const useEliminarBlog = () => {
    // Maneja la caché
    const queryClient = useQueryClient()
    return useMutation({
        mutationFn: eliminar, // Referencia al servicio
        // Si la mutación es exitosa
        onSuccess: () => {
           // Forzar recarga de la lista desde el backend
            queryClient.invalidateQueries(['blogs'])
        },
        // Si la mutación falla
        onError: (error) => {
            console.error('Error al eliminar el blog:', error.response?.data?.error || error.message)
        }
    })
}

// Mutación para dar like a un blog
export const useLikeBlog = () => {
    // Maneja la caché
    const queryClient = useQueryClient()
    return useMutation({
        mutationFn: like, // Referencia al servicio
        // Si la mutacción es exitosa
        onSuccess: () => {
            // Forzar recarga de la lista desde el backend
            queryClient.invalidateQueries(['blogs'])
        },
        // Si la mutación falla
        onError: (error) => {
            console.error('Error al dar like al blog:', error.response?.data?.error || error.message)
        }
    })
}