// Contexto para compartir el esatdo de los blogs (Prop Drilling)
import React from 'react'
import { createContext, useContext } from 'react' // Crear y usar el Context 
import { useQuery } from  '@tanstack/react-query' // Hook de Query para las peticiones
import { obtenerBlogs } from '../servicios/blogs_servicios' // Servicios
import { useCrearBlog, useEliminarBlog, useLikeBlog } from '../mutaciones/blogsMutaciones' // Mutaciones

// Context
const BlogsContext = createContext()
// Hook personalizado para encspsular el context completo
export const useBlogs = () => useContext(BlogsContext)

// Componente proveedor para que los componentes hijos accedan al Context
export const BlogsProvider = ({ children }) => {
    // Obtener los datos con Query
    const resultado = useQuery({
        queryKey: ['blogs'], // Clave única para la consulta
        queryFn: obtenerBlogs, // Referencia al servicio
        retry: 1, // 1 solicituda *Manejo de Errores*
        refetchOnWindowFocus: false // Evita recargas innecesarias
    })

    // Hooks con las mutaciones
    const crear = useCrearBlog()
    const eliminar = useEliminarBlog()
    const like = useLikeBlog()

    console.log(JSON.parse(JSON.stringify(resultado))) // Imprime el objeto más limpio en la consola

    // Funciones de acción
    // Función de acción para crear un blog
    const crearBlog = (blog) => {
        crear.mutate(blog)
    }
    // Función de acción para eliminar un blog
    const eliminarBlog = (blog) => {
        eliminar.mutate(blog)
    }
    // Función para dar like a un blog
    const likeBlog = (blog) => {
        like.mutate(blog.id)
    }


    // Proveer los valores al context
    return (
        <BlogsContext.Provider
        value={{
            blogs: resultado.data || [],
            crearBlog,
            eliminarBlog,
            likeBlog
        }}
        >
            {children}
        </BlogsContext.Provider>
    )
}