// Componente para mostrar la lista de blogs
import React from 'react'
import Blog from './Blog' // Componente del blog individual
import { useBlogs } from '../../contextos/BlogsContexto' // Hook del contexto

const BlogsLista = () => {
    // Instancia para acceder a los blogs
    const { blogs, eliminarBlog, likeBlog } = useBlogs()

    // Función para manejar la eliminación de un blog
    const handleEliminar = (blog) => {
        if (window.confirm(`¿Está seguro que desea eliminar el blog ${blog.titulo}?`)) {
            eliminarBlog(blog)
        }
    }
    // Función para manejar los likes 
    const handleLike = (blog) => {
        likeBlog(blog)
    }

    return (
        <div>
            <h1>Lista de Blogs</h1>
            <div>
                {blogs.map((blog) => (
                    <Blog
                    key={blog.id}
                    blog={blog}
                    handleEliminar={() => handleEliminar(blog)}
                    handleLike={() => handleLike(blog)}
                    />
                ))}
            </div>
        </div>
    )
}

export default BlogsLista