// Componente para el Menú de Navegación
import React from 'react'
import { Link } from 'react-router-dom' // Modulo para redirecciones dinamicas

const Menu = () => {
    const padding = {
        padding: 5
    }
    return (
        <div>
            <Link style={padding} to={'/'}>Blogs</Link>
            <Link style={padding} to={'/añadir_blog'}>Añadir Blog</Link>
        </div>
    )
}

export default Menu