// Hook personalizado para manejar los campos del formulario
import { useState } from 'react' 

export const useCampo = (name, type) => {
    const [value, setValue] = useState('') // Estado para el valor del campo de entrada

    // Función para agregar valor al campo de entrada
    const onChange = (e) => {
        setValue(e.target.value)
    }

    // Función para limpiar el formulario
    const limpiar = () => {
        setValue('')
    }

    return {
        inputProps: {
            name,
            type,
            value,
            onChange
        },
        limpiar
    }
}