// Componente con las Rutas
import React from 'react'
import BlogsLista from '../Blogs/BlogsLista'
import AñadirBlog from '../Blogs/BlogForm'

// Librería de React-Router (necesarias para la navegación entre páginas)
import {
    Routes, // Contenedor de Rutas
    Route // Ruta Individual
} from 'react-router-dom'

const Rutas = () => {
    return (
        <Routes>
            <Route path='/' element={<BlogsLista />} />
            <Route path='/añadir_blog' element={<AñadirBlog />} />
        </Routes>
    )
}

export default Rutas